import { mkdir, lstat, unlink, open, readFile, writeFile, rm } from 'node:fs/promises';
import { constants } from 'node:fs';
import { resolve } from 'node:path';
import { promisify } from 'node:util';
import { execFile as run } from 'node:child_process';
import { createHash } from 'node:crypto';
import { createEngine } from '../../packages/ssconvert/dist/index.js';
const execFile=promisify(run);
const root=resolve('out/ssconvert-gap-resolution/host-fifo-partial-qualification');
await mkdir(root,{recursive:false,mode:0o700});
const fixture=JSON.parse(await readFile('docs/ssconvert/linux-optional-service-native-probes.json','utf8'));
const cases=[];
try{
 for(const test of fixture.inputs.filter(i=>i.id==='datasource-live-solver')){
  const path=resolve(root,test.id+'.fifo');
  const receipt={id:test.id,explicitPath:path,platform:process.platform,opened:0,polled:0,descriptorClosed:0,ownedFifoUnlinked:0,producerBytesWritten:0,bytesRead:0};
  const engine=createEngine({codecs:[],environment:{env:{},locale:'C',timezone:'UTC'},limits:{inputBytes:100000,outputBytes:100000,cells:1000,sheets:4,operations:10000,workbookWork:1000000},
   solver:{async goalSeek(book){return book;},async solve(book,context){
    const first=await context.datasource.poll(book);
    receipt.firstPollValues=first.sheets[0].cells.map(cell=>cell.value);
    if(first.sheets[0].cells[3].value.kind!=='error'||first.sheets[0].cells[3].value.value!=='#N/A')throw new Error('Partial record was prematurely published');
    const delivered=await execFile('python3',['-c','import os,sys;fd=os.open(sys.argv[1],os.O_WRONLY|os.O_NONBLOCK|os.O_NOFOLLOW);print(os.write(fd,bytes.fromhex(sys.argv[2])));os.close(fd)',path,Buffer.from('17\n').toString('hex')]);
    receipt.secondProducerBytesWritten=Number(delivered.stdout.trim());
    const second=await context.datasource.poll(first);
    receipt.secondPollValues=second.sheets[0].cells.map(cell=>cell.value);
    if(second.sheets[0].cells[3].value.value!==17||second.sheets[0].cells[4].value.value!==18)throw new Error('Partial record/dependent failed');
    const updated=await execFile('python3',['-c','import os,sys;fd=os.open(sys.argv[1],os.O_WRONLY|os.O_NONBLOCK|os.O_NOFOLLOW);print(os.write(fd,bytes.fromhex(sys.argv[2])));os.close(fd)',path,Buffer.from('stock:23\n').toString('hex')]);
    receipt.thirdProducerBytesWritten=Number(updated.stdout.trim());
    const third=await context.datasource.poll(second);
    receipt.thirdPollValues=third.sheets[0].cells.map(cell=>cell.value);
    if(third.sheets[0].cells[3].value.value!==23||third.sheets[0].cells[4].value.value!==24)throw new Error('Later tag/dependent failed');
    return third;
   }},datasource:{async open(context){
    receipt.opened++;
    let handle,owned=false,released=false;
    const release=async()=>{
     if(released)return;released=true;
     if(handle){await handle.close();receipt.descriptorClosed++;handle=undefined;}
     if(owned){await unlink(path);receipt.ownedFifoUnlinked++;owned=false;}
    };
    context.own(release);
    // This explicit host adapter owns only this scratch FIFO. No ambient HOME/atl.
    try{
     await execFile('python3',['-c','import os,sys;os.mkfifo(sys.argv[1],0o600)',path]);owned=true;
     context.signal.throwIfAborted();
     const status=await lstat(path);if(!status.isFIFO())throw new Error('Owned path is not a FIFO');
     receipt.mode=(status.mode&0o777).toString(8);
     handle=await open(path,constants.O_RDWR|constants.O_NONBLOCK|constants.O_NOFOLLOW);
     context.signal.throwIfAborted();
     const delivered=await execFile('python3',['-c','import os,sys;fd=os.open(sys.argv[1],os.O_WRONLY|os.O_NONBLOCK|os.O_NOFOLLOW);print(os.write(fd,bytes.fromhex(sys.argv[2])));os.close(fd)',path,Buffer.from('stock:').toString('hex')]);
     receipt.producerBytesWritten=Number(delivered.stdout.trim());
     context.signal.throwIfAborted();
     return {async poll(signal){
      receipt.polled++;const chunks=[];
      while(true){
       signal.throwIfAborted();
       const buffer=new Uint8Array(4096);
       try{
        const result=await handle.read(buffer,0,buffer.length,null);
        if(!result.bytesRead)break;
        receipt.bytesRead+=result.bytesRead;
        if(receipt.bytesRead>context.limits.inputBytes)throw new Error('Host transport byte budget exceeded');
        chunks.push(buffer.slice(0,result.bytesRead));
       }catch(error){if(error.code==='EAGAIN'||error.code==='EWOULDBLOCK')break;throw error;}
      }
      return chunks;
     },close:release};
    }catch(error){await release();throw error;}
   }}});
  try{
   const input=new Uint8Array(Buffer.from(test.inputHex,'hex'));const chunks=[];
   const result=await engine.convert({input:{kind:'stream',filename:test.filename,source:[input]},solve:true,recalc:true,exportType:'Gnumeric_stf:stf_csv',destination:{kind:'stream',sink:{async write(bytes){chunks.push(Buffer.from(bytes));}}}}, {signal:new AbortController().signal});
   receipt.stdoutHex=Buffer.concat(chunks).toString('hex');receipt.csv=Buffer.concat(chunks).toString();receipt.exitCode=result.exitCode;receipt.diagnostics=result.diagnostics;
   receipt.inputUnchanged=createHash('sha256').update(input).digest('hex')===test.inputSha256;
  }finally{await engine.dispose();}
  try{await lstat(path);receipt.fifoPresentAfterSettlement=true;}catch(error){if(error.code!=='ENOENT')throw error;receipt.fifoPresentAfterSettlement=false;}
  if(receipt.csv!=='0,0,0,23,24\n')throw new Error('Unexpected host event-only callback result');
  if(receipt.descriptorClosed!==1||receipt.ownedFifoUnlinked!==1||receipt.fifoPresentAfterSettlement)throw new Error('Host resources retained');
  cases.push(receipt);
 }
 await writeFile('out/ssconvert-gap-resolution/datasource-host-fifo-partial-results.json',JSON.stringify(cases,null,2)+'\n');
 for(const c of cases)process.stdout.write(c.id+' write'+c.producerBytesWritten+'/read'+c.bytesRead+' close'+c.descriptorClosed+' unlink'+c.ownedFifoUnlinked+'\n');
}finally{await rm(root,{recursive:true});}
